# Fix the add_trigger function to handle both single images and batches
def add_trigger(img, corner='tl', pattern='white', size=3):
    """Add trigger to image. corner: tl, tr, bl, br. pattern: white, checkerboard, noise. size: 3-5.
    img can be (3, 32, 32) or (N, 3, 32, 32)"""
    img = img.clone()
    if img.dim() == 3:
        img = img.unsqueeze(0)
        squeeze = True
    else:
        squeeze = False

    n, c, h, w = img.shape
    if corner == 'tl':
        r, c_start = 1, 1
    elif corner == 'tr':
        r, c_start = 1, w - size - 1
    elif corner == 'bl':
        r, c_start = h - size - 1, 1
    elif corner == 'br':
        r, c_start = h - size - 1, w - size - 1

    if pattern == 'white':
        patch = torch.ones(c, size, size, dtype=torch.uint8) * 255
    elif pattern == 'checkerboard':
        patch = torch.zeros(c, size, size, dtype=torch.uint8)
        for i in range(size):
            for j in range(size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 255
    elif pattern == 'noise':
        patch = torch.randint(0, 2, (c, size, size), dtype=torch.uint8) * 255
    else:
        raise ValueError(pattern)

    img[:, :, r:r+size, c_start:c_start+size] = patch
    if squeeze:
        img = img.squeeze(0)
    return img

